-- Top 100 laboratory-equipment manufacturers; generated 2026-10-15
BEGIN;
CREATE TABLE manufacturers (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  aka TEXT,
  hq_city TEXT,
  hq_country TEXT,
  parent TEXT,
  ownership TEXT,
  founded INTEGER,
  website TEXT,
  category TEXT,
  employees INTEGER,
  employees_year INTEGER,
  employees_note TEXT,
  employees_scope TEXT,        -- company | parent | estimate
  revenue_original TEXT,
  revenue_usd_m REAL,
  revenue_year TEXT,
  revenue_scope TEXT,          -- company | segment | parent | estimate
  revenue_note TEXT,
  size_basis TEXT,             -- reported | estimate | mixed
  israel_presence TEXT,        -- subsidiary | distributor | parent_subsidiary | none_found | unclear
  israel_check TEXT,           -- verified | partial | unverified | pending
  israel_note TEXT,
  confidence TEXT,             -- high | medium | low
  confidence_note TEXT
);
CREATE TABLE products (
  manufacturer_id INTEGER NOT NULL REFERENCES manufacturers(id),
  rank INTEGER NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  PRIMARY KEY (manufacturer_id, rank)
);
CREATE TABLE israel_entities (
  id INTEGER PRIMARY KEY,
  manufacturer_id INTEGER NOT NULL REFERENCES manufacturers(id),
  name TEXT NOT NULL,
  name_he TEXT,
  type TEXT,                   -- subsidiary | distributor | service
  scope TEXT,
  website TEXT,
  source TEXT
);
CREATE TABLE sources (
  manufacturer_id INTEGER NOT NULL REFERENCES manufacturers(id),
  url TEXT NOT NULL
);
COMMIT;
