INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (2, 'Agilent Technologies', 'Agilent, BioTek, Dako, Agilent CrossLab', 'Santa Clara, California', 'USA', '', 'Public (NYSE: A)', 1999, 'https://www.agilent.com', 'Diversified analytical & life-science instruments', 18000, 2024, 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). FY2024 Form 10-K: approximately 18,000 employees (FY2025 10-K figure not checked).', 'USD 6.51 billion', 6510, 'FY2024 (ended 31 Oct 2024)', 'company', 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). FY2025 (ended 31 Oct 2025) revenue was reported around USD 6.9-7.0 billion but is not verified here.', 'reported', 'distributor', 'Agilent''s own Israel contact page lists Eldan Electronic Instruments (Kiryat Gat / Petah Tikva, Neopharm group) as its authorised distributor; Eldan''s site says it has represented Agilent for over four decades. Whether Agilent also has a direct office for genomics/cell analysis (BioTek) remains to be checked.', 'medium', 'Israel: one official-source entity supplied by the brief, not re-verified and not checked for completeness. Low: identity/products from model knowledge; size figures recalled from published reports but not verified in-session; Israeli presence not researched (search budget exhausted, WebFetch/curl blocked). Needs a follow-up research run.', 'company', 'verified');
