INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (5, 'Bruker Corporation', 'Bruker BioSpin, Bruker Daltonics, Bruker AXS, Bruker Nano, Bruker Optics, Bruker Cellular Analysis, NanoString, ELITechGroup', 'Billerica, Massachusetts', 'USA', '', 'Public (Nasdaq: BRKR)', 1960, 'https://www.bruker.com', 'Diversified analytical & life-science instruments', 9900, 2024, 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). Approximately 9,900 employees (2024 10-K); 2025 figure not checked.', 'USD 3.37 billion', 3366, 'FY2024', 'company', 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). FY2024 revenue USD 3,366 million; FY2025 (~USD 3.4-3.5 billion) not verified.', 'reported', 'subsidiary', 'One scope-clarification search (Bruker + Israel + NMR/MS/AXS/Lapidot). Bruker''s own Israel support page (English, Japanese and Spanish versions, 2025-2026) names Lapidot Medical Import and Marketing Ltd., Caesarea Industrial Park, as the Israel contact and says mass-spectrometry questions go to Bruker''s office in Gedera, Israel. No division-specific (NMR/AXS/Nano/microCT) partner listings appeared, so Lapidot appears to be the general Israeli partner while MS is handled by Bruker''s own local office; the Gedera entity''s legal name and the exact split of duties were not visible and Lapidot''s own site was not checked.', 'high', 'Both Israeli entities come from Bruker''s official support page; division-level scope and the Gedera entity name remain unconfirmed.', 'company', 'verified');
