INSERT INTO products (manufacturer_id, rank, name, description) VALUES (5, 3, 'D8 ADVANCE / Dimension AFM', 'X-ray diffraction and atomic force microscopy systems');
INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, source) VALUES (12, 5, 'Lapidot Medical Import and Marketing Ltd.', '', 'distributor', 'Bruker''s official Israel contact/partner (Caesarea Industrial Park); the Bruker Israel page covers the Bruker business generally - no separate NMR / AXS / Nano / microCT listings were visible', 'https://www.lapidot.com', 'https://www.bruker.com/en/services/support/india-middleeast-africa/israel-caesarea.html');
INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, source) VALUES (13, 5, 'Bruker - Israel office, Gedera (mass spectrometry)', '', 'subsidiary', 'mass-spectrometry (Bruker Daltonics) enquiries are directed to Bruker''s own office in Gedera, Israel; legal entity name not shown on the page', 'https://www.bruker.com', 'https://www.bruker.com/en/services/support/office.india-middle-east-africa.israel-caesarea.html');
