INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (9, 'Revvity', 'formerly PerkinElmer, Inc. (renamed May 2023); EUROIMMUN, BioLegend, Horizon Discovery, Nexcelom, Oxford Immunotec, Cisbio/HTRF, Dharmacon, Omni', 'Waltham, Massachusetts', 'USA', '', 'Public (NYSE: RVTY)', 1937, 'https://www.revvity.com', 'Life-science instruments & reagents', 11000, 2025, '11,000+ employees per Revvity 2025 Corporate Fact Sheet (March 2025)', 'USD 2.76 billion', 2755, 'FY2024', 'company', 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). FY2024 revenue USD 2,755 million; FY2025 (~USD 2.8 billion) not verified.', 'reported', 'distributor', 'Searched Revvity Israel distributor/נציג/יבואן, Israeli distributor domains (Revvity OR PerkinElmer), revvity.com and a ''Revvity Israel'' entity search. No Revvity Israeli subsidiary or office was found: revvity.com''s office/distributor listing and the 2023 SEC Exhibit 21 subsidiary list show no Israel entity, and the 2013 ''PerkinElmer establishes direct operations in Israel'' release (now on ir.revvity.com) refers to the Ra''anana office that today is listed by PerkinElmer (the analytical company), not Revvity. Gamidor''s own site says it represents Revvity for prenatal screening and Enco''s catalogue sells Revvity plates/reagents; no Israeli partner was found for Revvity life-science instruments (EnVision, Opera Phenix) or for newborn-screening instruments, which may be sold directly from abroad or via an unidentified channel.', 'medium', 'Distributor-site evidence for diagnostics reagents and consumables; coverage of instruments and newborn screening unverified; no manufacturer-side confirmation.', 'company', 'verified');
