INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (10, 'PerkinElmer (New Mountain Capital)', 'PerkinElmer analytical, enterprise & food businesses carved out of the former PerkinElmer (now Revvity) in 2023; NexION, Avio, Spectrum, Lambda, Pyris, OneSource', 'Shelton, Connecticut', 'USA', 'New Mountain Capital', 'Private equity (New Mountain Capital, since March 2023)', 1937, 'https://www.perkinelmer.com', 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 6000, 2024, '''more than 6,000 employees'' per March 2024 Chromatography Online interview with PerkinElmer''s CEO and CCO (company statement, not an annual report)', 'USD 1.3 billion (estimate)', 1300, 'FY2022 (at carve-out)', 'estimate', 'ESTIMATE: the divested PerkinElmer analytical/enterprise/food businesses were described as roughly USD 1.3 billion in annual revenue when the sale to New Mountain Capital was announced (Aug 2022, closed Mar 2023). Private company; no published current revenue; not verified in this session.', 'estimate', 'subsidiary', 'Searched PerkinElmer Israel distributor/נציג/יבואן (ICP/GC/FTIR), perkinelmer.com office/distributor pages and a 2024-2026 ''PerkinElmer Israel Ltd'' news search. PerkinElmer set up direct sales/service operations in Israel in August 2013 (press release; GM Aaron Geist named in 2015) and perkinelmer.com currently lists a PerkinElmer Israel office/PerkinElmer Israel Ltd. in Ra''anana plus ISI Israel Scientific Instruments Ltd. (Petach Tikva) as an Israeli partner for food testing. After the 2023 split the Israel entity stayed with the analytical company (now New Mountain Capital-owned PerkinElmer) rather than Revvity; no 2024-2026 Israel-specific news was found, so current staffing/scope of the Ra''anana office rests on the manufacturer''s current listing only.', 'high', 'Manufacturer''s own office-locations page names the Israeli subsidiary and partner; no recent independent confirmation.', 'company', 'verified');
