INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (12, 'Avantor (incl. VWR)', 'VWR; J.T.Baker; Macron Fine Chemicals; NuSil; Masterflex', 'Radnor, Pennsylvania', 'USA', '', 'Public (NYSE: AVTR)', 1904, 'https://www.avantorsciences.com', 'Lab distribution & own-brand products', 13500, 2025, 'Figure shown consistently by PitchBook, Tracenable and Motley Fool (likely from the FY2025 10-K human-capital section); Revelio Labs shows ~14,600. The 10-K (sec.gov avtr-20251231.htm) could not be opened (fetch failure).', 'USD 6.55 billion', 6552, 'FY2025', 'company', 'Company Q4/FY2025 press release: net sales USD 6.55B, down 3% (organic -3%); net loss USD 530M. EDGAR-derived figure 6,552 (USD millions) vs 6,784 in FY2024.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). No Israeli subsidiary, office or distributor found. Searched ''Avantor VWR Israel distributor'' (English) and ''VWR ישראל יבואן מוצרי מעבדה Avantor'' (Hebrew). VWR''s regional listings show a Dubai (Dubai Science Park) office for the Middle East and no Israeli entity; Avantor''s ''200+ facilities in 30+ countries'' statement does not mention Israel. Could NOT open the vwr.com country selector / avantorsciences.com ''where to buy'' page or candidate Israeli distributor sites (e.g. Bio-Lab, Tamar) because the fetch tool failed and the shared search budget ran out before domain-restricted searches. Treat as an incomplete search rather than a definitive absence; in practice Israeli labs may buy VWR/J.T.Baker lines through local chemical/lab distributors.', 'low', 'Size is from the company''s FY2025 results release. Israel result is low-confidence: manufacturer''s own distributor page and candidate distributor sites were not checked due to tool failures.', 'company', 'partial');
