INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (14, 'QIAGEN', 'QIAGEN; QIAstat-Dx; QuantiFERON; Genoox', 'Venlo (statutory seat); operational HQ Hilden, Germany', 'Netherlands', '', 'Public (NYSE: QGEN; Frankfurt: QIA)', 1984, 'https://www.qiagen.com', 'Life-science instruments & reagents', 6000, 2025, 'Approximate: QIAGEN''s corporate boilerplate states ''more than 6,000 employees''; the exact 2025 annual-report figure was not retrieved in this session (search budget exhausted). Company materials seen describe 35 subsidiaries in 25+ countries and distribution partners in 60+ countries.', 'USD 2.09 billion', 2090, 'FY2025', 'company', 'FY2025 net sales USD 2.09B vs USD 1.98B in 2024 (~+5% CER); net income USD 424.9M (360Dx/GenomeWeb coverage of the Q4 2025 release). QIAGEN reports in USD.', 'mixed', 'distributor', 'Searched QIAGEN Israel distributor/נציג/יבואן, Israeli distributor domains and qiagen.com. Ilex Medical''s own catalogue lists QIAGEN instruments and kits (QIAcuity, Rotor-Gene Q, QIAxcel, extraction, oncology), while Eldan''s site named QIAGEN as a represented manufacturer in 2014 and exhibited QIAGEN products in 2015-2016 - stale, so Eldan may no longer carry the line or may cover research-only products. QIAGEN''s own pages route Israel to ''a commercial partner in your country'' without naming one (a 2000 handbook named Westburg (Israel) Ltd., obsolete), and no QIAGEN Israeli subsidiary was found; QIAGEN''s acquisition of Israeli start-up Genoox is an R&D deal, not a sales channel. No source was seen for QIAsymphony/QIAstat-Dx specifically.', 'medium', 'Distributor-site evidence (Ilex current, Eldan stale); no confirmation on QIAGEN''s site and the research-vs-clinical split between distributors is unverified.', 'company', 'verified');
