INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (16, 'Beckman Coulter (Danaher)', 'Beckman Coulter Life Sciences; Beckman Coulter Diagnostics; Beckman Instruments; Coulter Corporation', 'Brea, California (Diagnostics); Indianapolis, Indiana (Life Sciences)', 'USA', 'Danaher Corporation', 'Subsidiary of Danaher Corporation (public, NYSE: DHR)', 1935, 'https://www.beckmancoulter.com', 'Clinical / IVD laboratory analyzers', 12000, 2025, 'Approximate combined headcount of Beckman Coulter Diagnostics (~11,000 per company statements) and Beckman Coulter Life Sciences; Danaher does not disclose operating-company headcount (parent ~60,000). Figures recalled from company statements / filings and not re-verified online in this session.', 'USD ~9.9 billion (Danaher Diagnostics segment, FY2025)', 9900, 'FY2025', 'segment', 'Danaher''s Diagnostics segment (Beckman Coulter Dx, Cepheid, Leica Biosystems, Radiometer); Beckman Coulter Life Sciences sits in the Life Sciences segment (~USD 7.3B). Beckman alone is not disclosed.', 'mixed', 'distributor', 'Life Sciences: Beckman Coulter Life Sciences'' own contact page for Israel (beckman.com/contact-us/israel, mirrored on mybeckman.vn) lists ''Rhenium Ltd (Distributor), 20 Hasatat, P.O.B. 180, Modi''in 7171101, Israel, +972 8 955 8888''. A 2009 Israel Physical Society trade-fair listing also names Beckman Coulter among the brands Rhenium represents. Diagnostics: no Israeli distributor or office was identified - the search (''Beckman Coulter diagnostics Israel distributor hematology DxH AU analyzer'') returned only regulatory recall records listing Israel among AU5800 distribution countries; the Hebrew query and a beckmancoulter.com domain search were blocked by the search budget and the Diagnostics site could not be opened (fetch failure). The Diagnostics channel therefore remains unverified and may be a different Israeli partner (the brief''s hints Ilex Medical / Dyn Diagnostics were not checked). Agentek appeared in results but shows no Beckman Coulter link.', 'medium', 'Life Sciences distributor comes from Beckman''s official contact page (high). Diagnostics channel unknown; size data are parent-level secondary figures.', 'estimate', 'verified');
