INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (17, 'Cytiva (Danaher)', 'GE Healthcare Life Sciences (former); Amersham; Whatman; HyClone; Pall life sciences (merged 2023)', 'Marlborough, Massachusetts', 'USA', 'Danaher Corporation', 'Subsidiary of Danaher Corporation (public, NYSE: DHR)', 2020, 'https://www.cytivalifesciences.com', 'Bioprocess & filtration', 16000, 2025, 'Cytiva states 16,000+ associates after absorbing Pall''s life-science business (2023). Figures recalled from company statements / filings and not re-verified online in this session.', 'USD 7.3 billion (Danaher Biotechnology segment)', 7300, 'FY2025', 'segment', 'Danaher Biotechnology segment (Cytiva incl. Pall life sciences) ~USD 7.3B FY2025; Cytiva alone not disclosed.', 'mixed', 'distributor', 'Searched generic queries (incl. ÄKTA/Whatman/Amersham), 27 Israeli distributor domains, cytivalifesciences.com and a Whatman-specific query. Danyel Biotech''s own site has a Cytiva brand page (ÄKTA pure chromatography; Biacore listed as a Cytiva supplier), so Danyel is a current Israeli channel. Cytiva''s ''find a distributor'' page lists Israel as a selectable country but the partner name was not visible in snippets, and Cytiva''s terms document lists Israel under its international contracting entity Pall Austria Filter Ges.m.b.H., i.e. direct contracts are also written from abroad. The 2009 Rhenium-for-Whatman listing could not be re-confirmed and no current Israeli Whatman/Amersham channel was found.', 'medium', 'Distributor evidence is the distributor''s own brand page; manufacturer-side naming of the Israeli partner was not visible and the scope across Cytiva''s many brands is unclear.', 'estimate', 'verified');
