INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (18, 'Leica Microsystems (Danaher)', 'Leica Microsystems GmbH; Leitz (heritage)', 'Wetzlar', 'Germany', 'Danaher Corporation', 'Subsidiary of Danaher Corporation (public, NYSE: DHR)', 1849, 'https://www.leica-microsystems.com', 'Light microscopy & imaging', 3500, 2025, 'Approximate Leica Microsystems headcount (company statements cite several thousand employees); parent Danaher ~60,000. Figures recalled from company statements / filings and not re-verified online in this session.', 'USD 7.3 billion (Danaher Life Sciences segment)', 7300, 'FY2025', 'segment', 'Danaher Life Sciences segment ~USD 7.3B FY2025 (Leica Microsystems, SCIEX, Molecular Devices, Beckman LS, Abcam, IDT, Aldevron…); Leica alone not disclosed.', 'mixed', 'distributor', 'Searched generic queries, 27 Israeli distributor domains, leica-microsystems.com, lapidot.com and rhenium.co.il. Lapidot Group''s own partner and eye-surgery pages show it markets Leica surgical microscopes in Israel, i.e. the Leica Microsystems medical division. For research microscopes (confocal, stereo, cryo-EM sample prep) the only evidence remains the 2009 Israel Physical Society listing naming Rhenium as exclusive representative; a 2026 search restricted to rhenium.co.il returned nothing, and Leica''s site shows no Israeli office (country selector only, ''contact your local representative''). The research-microscope channel is therefore unconfirmed and the Rhenium entry is stale.', 'medium', 'Surgical-microscope channel verified on the distributor''s own site; research-microscope channel rests on a 2009 listing and could not be re-verified.', 'estimate', 'verified');
