INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (32, 'Cytek Biosciences', 'Cytek; Cytek Amnis (ImageStream / Guava, acquired from Luminex 2023)', 'Fremont, California', 'USA', '', 'Public (NASDAQ: CTKB)', 2014, 'https://www.cytekbio.com', 'Cell analysis (flow cytometry / cell sorting)', 680, 2024, '~680 employees per 10-K FY2024 (recalled, unverified).', 'USD 201.5 million', 201.5, 'FY2025', 'company', 'FY2025 (year ended 31 Dec 2025) revenue USD 201.5 million, +1% vs USD 200.5 million in 2024; Q4-2025 USD 62.1 million (+8% YoY); GAAP gross margin 52% (10-K / Q4-2025 results release). Manufacturing in Fremont CA, Wuxi China and Singapore.', 'reported', 'distributor', 'Established from (1) a June-2022 Business Wire release (Slingshot Biosciences) stating Almog ''has been a major player in the Israeli flow cytometry field for over 13 years, with the automated MACSQuant (Miltenyi Biotec) and the innovative Aurora Spectral Flow Cytometer (Cytek Biosciences)''; (2) LinkedIn posts by an Almog employee (Dor Samet) announcing the Cytek Aurora Cell Sorter''s arrival in Israel and an on-site Aurora CS demo with Cytek at the Technion LS&E Infrastructure Center; (3) Aurora installations at Tel Aviv University (acquired 2025) and the Technion. Caveats: Cytek''s own distributor page and Almog''s website could not be opened (fetch blocked) and the ''site:almog.co.il Cytek'' query hit the search cap, so the relationship is confirmed by third-party/social sources rather than by Cytek or Almog pages; Almog''s website URL is from memory, unverified. No Cytek Israeli subsidiary was seen.', 'medium', 'Revenue from the SEC 10-K (via search result); headcount not retrieved. Israeli distributor (Almog) supported by a 2022 press release plus recent LinkedIn/installation evidence, not by a Cytek-published distributor list.', 'estimate', 'verified');
