INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (33, 'Carl Zeiss AG – Research Microscopy Solutions', 'ZEISS; Carl Zeiss Microscopy GmbH; ZEISS Research Microscopy Solutions (RMS); Industrial Quality & Research segment', 'Oberkochen, Baden-Wuerttemberg (microscopy business unit in Jena)', 'Germany', 'Carl Zeiss AG (100% owned by the Carl Zeiss Foundation / Carl-Zeiss-Stiftung)', 'Private (foundation-owned; sub-group Carl Zeiss Meditec AG is listed, XETRA: AFX)', 1846, 'https://www.zeiss.com/microscopy', 'Light microscopy & imaging', 46622, 2025, 'ZEISS Group headcount, fiscal year 2024/25 (ended 30 Sep 2025): 46,622 (prior year 46,485); >7,300 in R&D. Research Microscopy Solutions headcount is not disclosed separately.', 'EUR 11.896 billion', 13086, 'FY2024/25 (ending Sep-2025)', 'parent', 'ZEISS Group revenue EUR 11.896 billion (+9%; EBIT EUR 1.552 billion, 13% margin). Segment split: Semiconductor Manufacturing Technology EUR 5.055 bn, Industrial Quality & Research EUR 2.334 bn (~USD 2,567 m; this segment contains Research Microscopy Solutions together with Industrial Quality Solutions - RMS alone is not disclosed), Medical Technology EUR 2.704 bn, Consumer Markets EUR 1.569 bn. (Carl Zeiss Meditec AG separately reported EUR 2,227.6 m revenue and 5,784 employees for FY2024/25.)', 'reported', 'unclear', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). ZEISS has an Israeli site (zeiss.co.il; legal entity Carl Zeiss SMS Ltd., Bar Lev) whose contact form lists Research Microscopy Solutions, and Getter Group says it represents Zeiss, but no confirmed microscopy sales channel was found. Searched ''Zeiss microscope Israel distributor/נציג/יבואן'', Hebrew ''זייס/קרל זייס מיקרוסקופ נציג'', the brand across the Israeli distributor domains, zeiss.com and zeiss.co.il, and LinkedIn. No Israeli distributor of ZEISS research/electron microscopes surfaced anywhere (none of the listed Israeli distributor sites shows ZEISS microscopes); the only ZEISS Israel presence found is the official zeiss.co.il site, published by Carl Zeiss SMS Ltd. (Bar Lev Industrial Park, Misgav), whose contact form accepts Research Microscopy Solutions inquiries, plus the semiconductor R&D unit Carl Zeiss SMT Ltd. in Karmiel (not relevant). Lens-only partners (OpteamX for industrial lenses, Lapidot for ZEISS lenses) are not microscopy channels. Most likely ZEISS microscopes are sold/serviced in Israel directly by the ZEISS organization (regional EMEA team via the ZEISS Israel site), but this was not confirmed by a source naming a microscopy sales/service team. Getter Group''s about page lists Zeiss among the brands it exclusively represents in Israel (~2 years old); whether this covers ZEISS research microscopes is not stated.', 'medium', 'ZEISS''s own Israeli legal entity and Israeli website are verified from zeiss.co.il, but the specific microscopy sales/service channel is unconfirmed; no distributor found after exhaustive searches.', 'parent', 'partial');
