INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (37, 'Hitachi High-Tech', 'Hitachi High-Technologies (name until 2020); Hitachi High-Tech Science; Hitachi High-Tech Analytical Science; Nissei Sangyo (original name)', 'Tokyo (Minato, Toranomon)', 'Japan', 'Hitachi, Ltd. (wholly owned since the 2020 tender offer and delisting)', 'Subsidiary of Hitachi, Ltd. (public, TSE: 6501)', 1947, 'https://www.hitachi-hightech.com', 'Electron microscopy & X-ray / materials characterization', 12400, 2025, 'Consolidated headcount ~12,000-12,500 (recalled, unverified).', 'JPY ~750 billion (estimate)', 5000, 'FY ending Mar-2025 (estimate)', 'estimate', 'Hitachi High-Tech has been wholly owned by Hitachi, Ltd. since 2020 and no longer publishes stand-alone results; order of magnitude from its last public filings and Hitachi segment data. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'unclear', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Hitachi High-Tech Israel Ltd. (Kiryat Gat) exists but services semiconductor equipment only; no Israeli channel for SEM/TEM or analytical instruments was found. Searched ''Hitachi High-Tech Israel distributor/נציג/יבואן'', ''Hitachi SEM/TM4000 Israel distributor'', the brand across the Israeli distributor domains, hitachi-hightech.com, hha.hitachi-hightech.com (analytical) and Eisenberg''s site. The only Israeli entity found is the subsidiary Hitachi High-Tech Israel, Ltd. in Kiryat Gat, which the company''s own filings describe as a semiconductor-equipment service business. No Israeli distributor or representative for Hitachi electron microscopes or analytical instruments was found; Hitachi''s analytical site only says it has 150+ distributors without naming Israel. A Quantum Design page mentioning an ''Italy and Israel'' branch concerns Hitachi tabletop SEM distribution in Southern Germany only and is not evidence for Israel.', 'low', 'Subsidiary verified from Hitachi High-Tech''s own network page, but the channel for lab instruments (SEM/TEM/analytical) remains unknown.', 'estimate', 'partial');
INSERT INTO products (manufacturer_id, rank, name, description) VALUES (37, 1, 'Regulus / SU series FE-SEM (e.g. SU8600, SU7000)', 'field-emission scanning electron microscopes');
