INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (38, 'TESCAN', 'TESCAN; TESCAN ORSAY HOLDING; TESCAN Brno; TESCAN XRE (micro-CT, Belgium)', 'Brno', 'Czech Republic', 'Shimadzu Corporation (acquisition completed 10 Jul 2026)', 'Subsidiary of Shimadzu Corporation (public, TSE: 7701) since July 2026', 1991, 'https://www.tescan.com', 'Electron microscopy & X-ray / materials characterization', 800, 2024, 'Approximately 700-800 employees worldwide (company statements, recalled).', 'EUR ~130 million (trade estimate; private)', 143, '2024 (estimate)', 'estimate', 'TESCAN Group (Brno) is privately held; revenue estimate from trade press / Czech register figures. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', 'Searched ''TESCAN Israel distributor/נציג/יבואן'', the brand across the Israeli distributor domains, tescan.com and ''PicoTech TESCAN''. TESCAN''s own distributor directory lists PicoTech Ltd. (Petah Tikva) for Israel, and a PicoTech SEM-division sales engineer''s LinkedIn post reports the first TESCAN/WITec Raman-SEM installed in Israel. Corporate change: Shimadzu completed the acquisition of all shares of TESCAN GROUP on 10 July 2026 (TESCAN is now a wholly owned Shimadzu subsidiary), which could affect the Israeli channel; PicoTech''s own website URL was not captured in search snippets.', 'high', 'Named on the manufacturer''s official distributor page; corroborated by LinkedIn.', 'estimate', 'verified');
