INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (39, 'Rigaku Holdings', 'Rigaku Corporation; Rigaku Americas; Rigaku Europe SE; Applied Rigaku Technologies', 'Akishima, Tokyo', 'Japan', '', 'Public (TSE Prime: 268A; IPO Oct 2023, previously Carlyle-controlled)', 1951, 'https://www.rigaku.com', 'Electron microscopy & X-ray / materials characterization', 2000, 2024, 'Approximately 2,000 employees (IPO prospectus, recalled).', 'JPY ~100 billion (estimate)', 670, 'FY2024 (estimate)', 'estimate', 'Rigaku Holdings (TSE Prime 268A, listed Oct 2023) reported revenue of roughly JPY 95-100 billion for FY2024 (recalled, unverified).', 'estimate', 'unclear', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched ''Rigaku Israel distributor/נציג/יבואן'', the brand across the Israeli distributor domains (including rhenium.co.il), rigaku.com and extended searches for ''Rigaku Rhenium''. The only distributor evidence is the 2009 IPS listing naming Rigaku among Rhenium''s lines; nothing current confirms or contradicts it (Rhenium''s site is not indexed in the results). Rigaku does have its own Israeli group company, Rigaku Semiconductor Instruments Ltd. (ex-XwinSys, Migdal HaEmek), but it is a semiconductor-metrology R&D/manufacturing unit, not a channel for XRD/XRF instruments. Presence therefore marked unclear: stale distributor hint plus an unrelated subsidiary.', 'low', 'Rhenium link rests on a 2009 trade-fair page only; the Israeli Rigaku subsidiary is verified but out of scope.', 'estimate', 'partial');
