INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, source) VALUES (57, 39, 'Rigaku Semiconductor Instruments Ltd. (formerly XwinSys Technology Development Ltd.)', '', 'subsidiary', 'Rigaku Group company doing R&D and manufacturing of X-ray semiconductor metrology tools (Ramat Gabriel Industrial Zone, 6 HaMehkar St, Migdal HaEmek; rsi@rigaku.com, +972-4-9951051); joined Rigaku 2019, renamed Dec 2024. Not a sales channel for analytical XRD/XRF.', 'https://rigaku.com/about/rigaku-divisions/rigaku-semiconductor-instruments-ltd', 'https://rigaku.com/about/rigaku-divisions/rigaku-semiconductor-instruments-ltd');
