INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (40, 'HORIBA', 'HORIBA Scientific; HORIBA Jobin Yvon; HORIBA ABX (medical); HORIBA STEC; HORIBA Advanced Techno', 'Kyoto', 'Japan', '', 'Public (TSE: 6856)', 1945, 'https://www.horiba.com', 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 9000, 2024, 'Consolidated group headcount approx. 9,000 (end-2024). Figures recalled from company reports, NOT verified in this session (web tools unavailable) - verify before use.', 'JPY 306 billion', 2050, 'FY2024 (Dec-2024)', 'company', 'Consolidated net sales approx. JPY 306 billion in FY2024 (record; segments: Energy & Environment/automotive, Bio & Healthcare, Materials & Semiconductor incl. HORIBA STEC). FY2025 (Dec-2025) results not checked. Figures recalled from company reports, NOT verified in this session (web tools unavailable) - verify before use.', 'reported', 'distributor', 'Searched ''HORIBA Israel distributor/נציג/יבואן'', the brand across the Israeli distributor domains, horiba.com, ''HORIBA Medical/ABX/Yumizen Israel'' and ''New-Road Agencies''. HORIBA''s worldwide-locations page lists two Israeli partners: Agrolan Ltd (water quality only; also on the LAQUA distributor page for Israel) and New-Road Agencies Ltd (scientific); HORIBA has no Israeli office (its only Middle East base is HORIBA Middle East in the UAE, created June 2026 by acquiring distributor FANDA). No Israeli distributor for HORIBA Medical (hematology) was found. Caveat: the HORIBA pages are roughly 3-4 years old and neither distributor''s own site was seen, so current status should be confirmed.', 'medium', 'Both entities named on HORIBA''s own pages, but the listings are dated, no distributor-side confirmation, and the medical division channel is unknown.', 'company', 'verified');
