INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (41, 'Malvern Panalytical (Spectris)', 'Malvern Instruments, PANalytical (Philips Analytical heritage); Spectris Scientific division', 'Malvern, Worcestershire (second HQ: Almelo, Netherlands)', 'UK', 'Spectris (owned by KKR since December 2025)', 'Subsidiary of Spectris — Private equity (KKR; GBP 4.7bn take-private completed December 2025, Spectris delisted 5 Dec 2025)', 2017, 'https://www.malvernpanalytical.com', 'Electron microscopy & X-ray / materials characterization', 7600, 2025, 'Spectris group headcount (~7,600, per 2025 take-private coverage). Malvern Panalytical''s own headcount was not obtained from a source in this session (it is generally described as roughly 2,000+ staff).', 'GBP 776.7 million', 1010, 'FY2024', 'segment', 'Spectris Scientific segment (Malvern Panalytical + Servomex etc.) FY2024; Spectris was taken private by KKR in Dec 2025 and no longer reports.', 'reported', 'distributor', 'Searched generic queries, 27 Israeli distributor domains and malvernpanalytical.com. Dr. Uri Golik Chemical Instrumentation has a current ''Malvern Panalytical'' manufacturer page and product pages for Zetasizer Pro, Mastersizer 3000+, NanoSight NS300, Morphologi 4, Archimedes and MicroCal PEAQ-DSC; Malvern''s own 2013 Isranalytica article calls Dr Golik its distributor (best-supplier award, CEO Dorit Bilman Golik) and a 2011 Malvern contact sheet attached to an Israeli government tender lists Golik, Tel Aviv, as Israel sales/service. Caveat: the manufacturer-side confirmations pre-date the 2017 Malvern/PANalytical merger, and XRD (ex-PANalytical) products were not seen on Golik''s pages.', 'high', 'Current distributor brand page corroborated by the manufacturer''s own (older) article and contact sheet.', 'parent', 'verified');
