INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (42, 'Oxford Instruments', 'Andor Technology, Oxford Instruments NanoAnalysis, Asylum Research, WITec, Oxford Instruments Plasma Technology, Magnetic Resonance; NanoScience (quantum business, sale agreed 2025)', 'Abingdon, Oxfordshire', 'UK', '', 'Public (LSE: OXIG)', 1959, 'https://www.oxinst.com', 'Electron microscopy & X-ray / materials characterization', 2200, 2025, 'Annual Report 2025 ''at a glance'' reads as ''2,200+ employees'' (text extraction ambiguous); operations in 23 countries, 27 base locations. Third-party aggregators show ~2,000.', 'GBP 500.6 million', 651, 'FY ending Mar-2025', 'company', 'FY2024/25 group revenue GBP 500.6m (prior year 470.4m), adjusted operating profit GBP 82.2m. NanoScience (quantum/cryogenics) contributed ~GBP 59m revenue and ~GBP 1m adjusted operating profit in FY25. FY2025/26 results (year to Mar-2026) were not retrieved in this session.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched ''"Oxford Instruments" Israel distributor'' and ''"Oxford Instruments" ישראל נציג'': no Israeli distributor or office was named in any result. Note the frequent confusion with Oxford Nanopore Technologies (a different company), whose Israeli channel partner is Zotal Ltd — that is NOT Oxford Instruments. A planned search for Andor''s Israeli distributor and fetches of oxinst.com / andor.oxinst.com / nano.oxinst.com distributor pages could not be run (search budget exhausted; hosts denied by egress proxy). Oxford Instruments Israel-related content found was only an ISM 2022 (Israel Society for Microscopy) event page, which names no distributor.', 'low', 'Size from official FY2025 results (high); Israeli channel search incomplete — nothing found but manufacturer distributor pages were not readable, so ''none_found'' is provisional.', 'company', 'partial');
