INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (43, 'Anton Paar', 'Anton Paar Group AG; Quantachrome Instruments (acquired 2018, now Anton Paar QuantaTec); Brabender (acquired 2023)', 'Graz', 'Austria', 'Anton Paar Group AG (owned by the charitable Santner Foundation)', 'Private (foundation-owned — Santner Foundation)', 1922, 'https://www.anton-paar.com', 'Diversified analytical & life-science instruments', 4500, 2025, '''4,500+ employees'' per the company factsheet (dated June 2026) and Wikipedia; Revelio Labs shows 2,816 (Sept 2025) for a narrower legal-entity scope.', 'EUR 629 million', 692, 'FY2025', 'company', 'Net sales revenue 2025 EUR 629m per Anton Paar factsheet (June 2026); 14.5% of turnover invested in R&D.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched ''"Anton Paar" Israel distributor'' and ''"Anton Paar" ישראל נציג'': no Israeli subsidiary or distributor was named. Anton Paar operates ~37 own subsidiaries worldwide; Israel is not among those seen. One lead: an Israeli LinkedIn profile (Keren Tenenbaum) posts about ''another advanced FTIR solution joining our installed base in Israel'' and an Autosorb 6200 (Anton Paar/Quantachrome) installed at Bar-Ilan University — indicating an active local channel whose company name was not visible. The manufacturer''s contact/sales-partner page (anton-paar.com/corp-en/about-us/contact/) and the factsheet could not be opened (host denied by egress proxy).', 'medium', 'Size from company factsheet (high); Israeli channel not established — search incomplete because the manufacturer''s partner page was unreachable.', 'company', 'partial');
