INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (47, 'SPECTRO Analytical Instruments (AMETEK)', 'SPECTRO (AMETEK Materials Analysis Division); SPECTRO ARCOS, SPECTROBLUE, SPECTROGREEN, SPECTRO XEPOS, SPECTROMAXx, SPECTRO MS', 'Kleve', 'Germany', 'AMETEK, Inc.', 'Subsidiary of AMETEK (public, NYSE: AME) — acquired 2005', 1979, 'https://www.spectro.com', 'Elemental & materials analysis', 500, 2024, 'SPECTRO (Kleve) employs roughly 400-500; parent AMETEK ~21,500 (recalled, unverified).', 'USD 6.94 billion', 6940, 'FY2024', 'parent', 'AMETEK group revenue (parent); SPECTRO alone is not disclosed (order of EUR 100-150M, trade estimate).', 'mixed', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched generic English/Hebrew queries, 27 Israeli distributor domains, spectro.com/ametek.com and agentek.co.il with SPECTRO product names (ARCOS, SPECTROBLUE, SPECTROGREEN, XEPOS, SPECTROMAXx). Nothing names an Israeli SPECTRO representative: Agentek''s catalog lists ICP/ICP-MS/XRF and metal-analysis spectrometer categories but its vendor pages (Shimadzu, Konica Minolta, etc.) never mention SPECTRO or AMETEK, so the Agentek hint is unconfirmed; SPECTRO''s ''worldwide'' locator and AMETEK''s global locations (Middle East office in Dubai) did not surface Israel in snippets. Result: no Israeli channel identified.', 'low', 'Four searches found neither a distributor nor manufacturer-side Israel contact; the Agentek lead is neither confirmed nor excluded.', 'estimate', 'partial');
