INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (51, 'Biotage', 'Biotage; Astrea Bioseparations; formerly Pyrosequencing AB (Biotage brand founded 1989 in the USA); Selekt, Sfär, Isolera, Extrahera, Initiator, Alstra', 'Uppsala', 'Sweden', 'KKR (via RWK BidCo AB)', 'Private equity (KKR) — public cash offer of SEK 145/share (SEK 11.6 bn / ~USD 1.2 bn) announced April 2025, completion reported June 2025; previously public (Nasdaq Stockholm: BIOT), now delisted', 1997, 'https://www.biotage.com', 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 700, 2025, 'Approx. 700 employees per Biotage''s own company description (April 2025 release: ''operates globally with 700 employees and serves customers in 80 countries''); third-party trackers show ~620-680. Founding year caveat: Swedish listed entity (Pyrosequencing AB) 1997; some databases (Yahoo profile) show 1969; the Biotage brand/US company dates to 1989.', 'SEK 2,056 million', 201, 'FY2024', 'company', 'Year-end report Jan-Dec 2024: net sales SEK 2,056 m (SEK 1,862 m in 2023), +10.5% reported / +1.0% organic. No FY2025 public report expected after the KKR take-private.', 'reported', 'distributor', 'Biotage''s own contact/distributor page (biotage.com/contact) lists ''BARGAL'' with the e-mail sales@bargal.co.il among its distributor contacts — seen via a search-engine extract of that page; the page itself and bargal.co.il could not be opened this session (WebFetch DNS failure; direct HTTPS blocked by the session proxy), so the listing was not confirmed on the distributor''s own site. No Biotage Israeli office found: Biotage''s own offices are in Sweden, USA, UK, China, Japan, South Korea and India and its corporate page says the Middle East is served through distributors. Searches run: ''Biotage Israel distributor'', ''Biotage ישראל נציג'', ''Biotage site:co.il''.', 'medium', 'Size figures from the 2024 year-end report and company description (seen via search extracts). Israeli distributor rests on a search-engine extract of Biotage''s own contact page, not confirmed on Bargal''s site. KKR completion seen only in a secondary M&A roundup (27 June 2025), not in a Biotage/KKR release.', 'company', 'verified');
