INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (56, 'Abbott Diagnostics', 'Abbott Core Laboratory Diagnostics; Abbott Rapid Diagnostics; Alinity; ARCHITECT; i-STAT; ID NOW; BinaxNOW; Panbio; Cell-Dyn', 'Abbott Park, Illinois', 'USA', 'Abbott Laboratories', 'Division of Abbott Laboratories (public, NYSE: ABT)', 1972, 'https://www.corelaboratory.abbott', 'Clinical / IVD laboratory analyzers', 114000, 2024, 'Abbott Laboratories total headcount (~114,000, Abbott 10-K for FY2024) — from memory, not verified this session; Diagnostics division headcount not disclosed. Founded: Abbott 1888; Diagnostics Division established 1972.', 'USD 9.3 billion (Diagnostic Products segment, approx.)', 9300, 'FY2024', 'segment', 'Abbott Diagnostic Products segment sales FY2024 ≈ USD 9.3 bn (Abbott total ≈ USD 42.0 bn); FY2025 Diagnostics ≈ USD 9 bn (lower COVID testing; approx., reported Jan 2026). From memory of Abbott 10-K / earnings releases; could not be verified this session (search budget exhausted, fetch failures) — verify.', 'reported', 'parent_subsidiary', 'Searched ''"Abbott" Israel Alinity/Architect distributor/יבואן'', Hebrew ''אבוט מעבדות רפואיות'', the 29 Israeli distributor domains, mr.gov.il and Abbott''s own domains. Abbott''s global-locations page lists Abbott Medical Laboratories Ltd. in Tel Aviv under ''Nutrition, Pharmaceuticals and Diagnostics'', and the Hebrew ''Abbott in Israel'' page (il.abbott) says the affiliate has ~160 employees and that its diagnostics work in Israel covers molecular and laboratory tests; Globes reported the representative office opened in 2004 and Abbott''s later expansion in Israel. No Israeli distributor for Alinity/Architect appeared on any distributor site. Caveat: no source states explicitly that the analyzers are sold and serviced by the affiliate itself, and the only tender hits concern Abbott Informatics (STARLIMS), not analyzers.', 'high', 'Israel finding only: entity named on Abbott''s own pages; direct channel for Alinity/Architect inferred from the affiliate''s diagnostics scope and absence of a distributor.', 'company', 'verified');
