INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (58, 'bioMérieux', 'BioFire Diagnostics; VITEK; BACT/ALERT; VIDAS; BIOFIRE FILMARRAY; SPOTFIRE; Specific Diagnostics', 'Marcy-l''Étoile (Lyon)', 'France', 'Institut Mérieux (controlling shareholder)', 'Public (Euronext Paris: BIM); majority-controlled by Institut Mérieux (Mérieux family)', 1963, 'https://www.biomerieux.com', 'Clinical / IVD laboratory analyzers', 14000, 2024, 'Approx. 14,000 employees in ~45 countries (bioMérieux 2024 reporting) — from memory, not verified this session.', 'EUR 3.98 billion (approx.)', 4378, 'FY2024', 'company', 'FY2024 sales ≈ EUR 3.98 bn (double-digit organic growth driven by BIOFIRE); FY2025 ≈ EUR 4.1-4.2 bn (approx., reported early 2026). From memory of bioMérieux results releases; not verified this session — verify.', 'reported', 'unclear', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched ''"bioMérieux" Israel distributor/Gamidor/יבואן'', Hebrew ''ביומרייה/VITEK/FilmArray יבואן'', the 29 Israeli distributor domains, a Gamidor/Hylabs/Ilex/Rhenium-only search and biomerieux.com. No source names an Israeli distributor or sales subsidiary for the clinical lines: Gamidor''s pages (microbiology, central laboratory) do not mention bioMérieux in any snippet, so the earlier Gamidor lead remains unconfirmed, and bioMérieux''s site only says it serves 160+ countries through its distributor network and to ''consult your local bioMérieux representative''. The only bioMérieux-owned Israeli entity found is Accellix in Jerusalem (acquired 2025), which is an R&D/manufacturing site. Marked ''unclear'' because distributors clearly exist (earlier FDA records, bioMérieux''s own wording) but none could be identified.', 'low', 'No Israeli sales entity identified for VITEK/BACT/ALERT/BIOFIRE; Gamidor hint neither confirmed nor refuted.', 'company', 'partial');
