INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (72, 'NuAire', 'NuAire Laboratory Equipment; brands: LabGard, In-VitroCell, Glacier, AireGard, NuWind', 'Plymouth, Minnesota', 'USA', 'Kewaunee Scientific (since Nov 2024)', 'Subsidiary of Kewaunee Scientific (public, NASDAQ: KEQU)', 1971, 'https://www.nuaire.com', 'Biosafety cabinets & clean-air equipment', 300, NULL, 'Third-party estimates: PitchBook ~300, Datanyze 267, ZoomInfo 201-500, other directories 114-200. NuAire''s site says it ''supports 350 Minnesota families'' (three facilities in Plymouth and Long Lake, MN, >300,000 sq ft). PitchBook labels ownership ''Acquired/Merged (Operating Subsidiary)'' without naming a parent; no parent found in sources seen.', 'approx. USD 96 million (third-party estimate)', 96, 'n/a (aggregator estimate seen Oct 2026)', 'estimate', 'Datanyze and ZoomInfo both list ~USD 96M; Visual Visitor gives USD 10-50M. No published figure (private company).', 'estimate', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched ''"NuAire" Israel distributor'' and Hebrew ''NuAire ישראל נציג מנדף ביולוגי''. Results only surfaced the unrelated UK ventilation company Nuaire''s distributor list (Poland, Turkey, Bahrain) and NuAire Inc.''s statements that it has >100 distributors worldwide with an online ''Sales Partner Locator''. The locator and any Israeli distributor sites could not be opened (fetch blocked) and no site:co.il search was possible (budget exhausted). No Israeli entity identified.', 'low', 'Size figures are aggregator estimates; Israel check incomplete (partner locator not opened).', 'company', 'partial');
