INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (73, 'PHC Holdings (PHCbi)', 'PHCbi; formerly Panasonic Healthcare / Panasonic Biomedical / Sanyo Biomedical; group brands Epredia, LSI Medience, Wemex, Ascensia', 'Tokyo (Minato-ku)', 'Japan', '', 'Public (TSE: 6523)', 1969, 'https://www.phchd.com', 'Lab refrigeration & cold storage', 9041, 2025, 'Consolidated PHC Holdings group headcount (Simply Wall St / TradingView, shown as of Dec 2025, presumably from the FY2024 report). The PHCbi biomedical business''s own headcount is not disclosed in sources seen. Founding year 1969 refers to PHC Corporation''s origin (Matsushita Kotobuki Electronics); PHC Holdings itself was established 2014 when KKR acquired Panasonic Healthcare.', 'JPY 361.6 billion', 2423, 'FY2024 (ending Mar-2025)', 'parent', 'Group revenue JPY 361.6bn (+2.2% YoY) per the CFO message in PHC''s Integrated Report 2025. The Diagnostics & Life Sciences segment (Epredia + PHCbi biomedical) was JPY 130.9bn (~USD 877M, +1.0%); the biomedical (PHCbi) sub-segment alone is not broken out in sources seen. PitchBook shows TTM revenue ~USD 2.42bn to Sep-2025. FY2025 (ending Mar-2026) results were not retrieved.', 'reported', 'distributor', 'Searched generic queries, 27 Israeli distributor domains, phchd.com and enco.co.il. Eldan Electronic Instruments'' laboratory-instruments page lists PHCbi CO2/multigas incubators (incl. Cell-IQ) and PHCbi biomedical/pharmaceutical freezers alongside Hettich, so Eldan is a current Israeli channel; the Enco lead could not be confirmed (a search restricted to enco.co.il returned no PHC content). PHCbi''s own ''where to buy'' lists partners for APAC and PHC Europe B.V. for Europe but Israel was not visible, and it states it is not recruiting new distributors. Lumitron''s own ''Our brands'' page lists PHCbi among the brands it distributes in Israel (seen in a search excerpt).', 'medium', 'Distributor''s own product page names PHCbi; manufacturer-side listing for Israel not seen.', 'parent', 'verified');
