INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (74, 'Haier Biomedical', 'Haier Biomedical; 海尔生物; Haier Biomedical UK; brands: Biobank, Smart Vaccine, DW ULT freezers', 'Qingdao, Shandong', 'China', 'Haier Group (controlling shareholder)', 'Public (SSE STAR Market: 688139); controlled by Haier Group', 2005, 'https://www.haiermedical.com', 'Lab refrigeration & cold storage', 2800, 2024, 'Roughly 2,500-3,000 employees (annual report, recalled).', 'CNY 2.32 billion (2,316 million)', 322, 'FY2025', 'company', 'Company press release (30 Apr 2026) on the 2025 annual report: revenue ~CNY 2.33bn (company''s own conversion USD 340.8M), overseas revenue CNY 840M = record 36% share; new businesses (smart medication, blood technology, lab solutions) 48.5% of revenue; R&D CNY 320M. StockAnalysis lists FY2025 operating revenue CNY 2,316M vs CNY 2,274M in FY2024 (~+2%). USD figure uses the brief''s 0.139 rate.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched ''"Haier Biomedical" Israel distributor'' and Hebrew ''Haier Biomedical ישראל מקפיא יבואן''. A company press release says Haier Biomedical is in the supply chains of leading pharma companies in countries including Israel, but names no Israeli partner; the company cites >800 dealer relationships in 160 countries. Hebrew results were only consumer Haier household freezers sold by the appliance importer (unrelated to Haier Biomedical lab equipment). The haiermedical.com contact/distributor page and any Israeli distributor sites could not be opened and no site:co.il search was possible. No Israeli entity identified.', 'low', 'Revenue is reported (press release + aggregator); headcount missing; Israel check incomplete.', 'estimate', 'partial');
