INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (78, 'Azenta Life Sciences', 'Azenta Life Sciences; formerly Brooks Automation (renamed 2021); brands: GENEWIZ, FluidX, Ziath, 4titude, Limfinity, FreezerPro, Barkey; B Medical Systems (divestiture agreed Dec 2025)', 'Burlington, Massachusetts', 'USA', '', 'Public (NASDAQ: AZTA)', 1978, 'https://www.azenta.com', 'Lab refrigeration & cold storage', 2700, 2025, 'Roughly 2,700 employees in continuing operations after the B Medical Systems divestiture (recalled, unverified).', 'approx. USD 585 million (FY2025 continuing operations; Q1-Q3 reported USD 435M, Q4 extrapolated)', 585, 'FY2025 (ended Sep-2025)', 'estimate', 'Reported quarterly revenue from continuing operations: Q1 USD 148M (+4%), Q2 USD 143M (+5%), Q3 USD 144M (flat) per Azenta press releases; the Q4/full-year figure was not retrieved, so the ~USD 585M full-year number is an extrapolation and must not be cited as reported. B Medical Systems is reported as discontinued operations (FY2025 revenue USD 68.0M vs 83.1M FY2024 and 113.1M FY2023; FY2025 net loss USD 79.5M mainly from the estimated loss on assets held for sale).', 'mixed', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched ''"Azenta" Israel distributor OR "Azenta Israel"''. No source named an Israeli distributor or an Azenta Israel entity; Wikipedia describes operations in North America, Europe and Asia only. The azenta.com contact/distributor pages could not be opened, and Hebrew/site:co.il searches for Azenta, GENEWIZ, FluidX and Ziath were not possible (budget exhausted). Corporate change: Azenta announced in Q1 FY2025 its plan to sell B Medical Systems; a definitive agreement with THELEMA S.a r.l. was signed 29 Dec 2025 with closing expected on or before 31 Mar 2026 (Taylor Wessing advised; closing not confirmed in sources seen). No Israeli entity identified.', 'low', 'Quarterly revenue is reported but the full year is extrapolated; headcount missing; Israel check incomplete.', 'estimate', 'partial');
