INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (79, 'Opentrons Labworks', 'Opentrons; products Flex, OT-2', 'Long Island City (Queens), New York', 'USA', '', 'Private (venture-backed; SoftBank-led USD 200M round in 2021 at USD 1.8bn valuation; SOSV/HAX alumnus)', 2014, 'https://opentrons.com', 'Liquid handling & lab automation', 208, 2026, 'Latka estimate (~208 in 2026, down from ~300 in 2024); other aggregators range from 100 to 501-1,000. Location sources: Prospeo says Queens, NY; a 2021 SOSV article says Brooklyn (pre-move).', 'approx. USD 45 million (2024, Latka estimate)', 45, '2024', 'estimate', 'Aggregator estimates conflict: Latka USD 45M (2024) vs Prospeo USD 12.3M. CB Insights lists a Series C-II of USD 20.1M on 5 Dec 2025; total funding estimates USD 233-271M. TrueUp shows a secondary-market valuation estimate of ~USD 0.2bn versus the 2021 USD 1.8bn headline.', 'estimate', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched ''"Opentrons" Israel distributor''. No Israeli distributor named; results list partners elsewhere (I&L Biosystems for Europe, MikroLab for the Nordics, a global distribution agreement with Copia Scientific announced Mar 2025, Arcis Biotechnology). Agentek surfaced generically with no Opentrons mention; SciRobotics (Israel) is a competitor, not a distributor. The opentrons.com distributors page could not be opened and Hebrew/site:co.il searches were not possible (budget exhausted). No Israeli entity identified.', 'low', 'Size figures are conflicting aggregator estimates; Israel check incomplete.', 'company', 'partial');
