INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (83, 'A&D Company (A&D HOLON Holdings)', 'A&D Company, Limited; A&D Weighing; A&D Instruments; A&D Engineering; Holon Create', 'Toshima-ku, Tokyo', 'Japan', '', 'Public (TSE: 7745)', 1977, 'https://www.aandd.jp', 'Lab balances & weighing', 2438, 2025, 'Consolidated A&D HOLON Holdings headcount per Simply Wall St (2,438); TipRanks lists 2,471 for an earlier period. A&D HOLON Holdings became the holding company of A&D Company and Holon Create in 2023; balances are made by the A&D Company subsidiary (Measurement & Weighing segment).', 'JPY 69,326 million', 464.5, 'FY ending Mar-2026', 'company', 'Consolidated net sales JPY 69,326 million (+3.3% YoY) per stockanalysis.com / envalith.com / logmi; operating income JPY 9,210 million. Segment net sales: Measurement & Weighing JPY 31,545 million, Medical & Health JPY 26,667 million, Semiconductor-related JPY 11,114 million.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Step 5(a) searches run: ''"A&D" balances Israel distributor "A&D Company"'', ''"A&D" משקל אנליטי site:co.il'' — none returned any Israeli page or distributor (hits were DKSH, VWR, UK/NZ/India resellers). Steps 5(b)/(c) could NOT be completed: the A&D worldwide network page (aandd.jp/network) and Israeli distributor sites were unreachable (WebFetch DNS failure, proxy 403) and the shared search budget was exhausted before Hebrew ''A&D יבואן'' variants could be run. Marked ''unclear'' rather than ''none_found''. No Israeli entity is asserted from memory.', 'low', 'Size data is consolidated and well sourced from financial-data sites (medium quality); Israeli representation could not be verified this run, which drives the overall rating down.', 'company', 'partial');
