INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (89, 'Kewaunee Scientific', 'Kewaunee, Nu Aire / NuAire (subsidiary since Nov 2024), Kewaunee Labway India', 'Statesville, North Carolina', 'USA', '', 'Public (NASDAQ: KEQU)', 1906, 'https://www.kewaunee.com', 'Lab furniture & fume hoods', 2800, 2025, 'Roughly 2,800 employees incl. India operations and Nu Aire (acquired Nov 2024); recalled, unverified.', 'USD ~246 million', 246, 'FY2025 (ended Apr-2025)', 'company', 'FY2025 (fiscal year ended April 30, 2025) net sales of roughly USD 246 million as recalled from Kewaunee''s FY2025 10-K/earnings release (includes Nu Aire from Nov 2024); FY2026 results (reported mid-2026) could not be retrieved. Flagged ''estimate'' because it could not be re-verified against a source this run.', 'mixed', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched generic English/Hebrew queries, 27 Israeli distributor domains, kewaunee.com and nuaire.com, a NuAire-Israel query and Israeli lab-furniture tender documents. Nothing names an Israeli dealer: Kewaunee lists sales offices only in the USA, India, Saudi Arabia and Singapore; its FY2026 annual report says 28% of revenue comes from outside the USA and that Nu Aire added distribution partners in new regions without naming them; a D&B profile says the Singapore/India subsidiaries cover Asia and the Middle East. NuAire''s site shows only an ''Israel outlet (Type H)'' plug option. Israel is therefore most likely served, if at all, from the Singapore/India/Saudi offices; no Israeli dealer could be identified.', 'medium', 'Five searches including the manufacturer''s own site and the Nu Aire subsidiary found no Israeli entity; absence is well supported but a small dealer could still exist offline.', 'estimate', 'partial');
