INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (91, 'DWK Life Sciences', 'DURAN, WHEATON, KIMBLE, KIMAX; formed from Duran Group, Wheaton Industries and Kimble Chase', 'Mainz (sources also cite Wertheim; US headquarters Millville, New Jersey)', 'Germany', 'One Equity Partners (portfolio company)', 'Private equity (One Equity Partners)', 2017, 'https://www.dwk.com', 'Labware & consumables (plastic & glass)', 1800, 2025, '''Over 1,800 employees worldwide'' per DWK''s own careers page (current); 12 manufacturing sites, presence in 50+ countries (ChromatographyToday profile). Third-party directories give 470-1,900.', 'USD 105.7 million', 106, 'FY2023', 'estimate', 'Preqin database figure (revenue c. USD 105.72M, EBITDA c. USD 11.51M, 2023); scope unclear and probably a single legal entity rather than the whole group. Other third-party estimates range from USD 50-100M (Seamless.AI), USD 101.8M (RocketReach) to USD 350M (Prospeo). No company-published revenue found.', 'mixed', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched: ''"DWK Life Sciences" Israel distributor'' and Hebrew ''DWK DURAN WHEATON KIMBLE יבואן ישראל''. No Israeli distributor, representative or office was named in any result; an undated Israeli Chamber of Commerce listing (2018) of a medical-device distributor appeared but was not tied to DWK. DWK sells through regional distributors (e.g. REATORG in Russia). Tooling caveat: the manufacturer''s own distributor/contact page could not be opened because the WebFetch tool returned DNS errors for every host during this run, and the shared WebSearch budget was exhausted before domain-restricted follow-up searches could run. Result reflects the English and Hebrew web searches only.', 'low', 'Headcount from company page; revenue only from conflicting third-party databases; Israeli channel not established (manufacturer page could not be opened).', 'company', 'partial');
