INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (96, 'INFORS HT', 'Infors AG; Multitron, Minifors, Labfors, eve bioprocess platform', 'Bottmingen (Basel-Land)', 'Switzerland', '', 'Private (family-owned)', 1965, 'https://www.infors-ht.com', 'Bioprocess & filtration', 200, 2015, '''About 200 staff'' reported at the company''s 50th anniversary (Technology Networks, 2015); Built In lists 179; other directories 100-250. Nine offices (CH, DE, UK, FR, NL, US, BR, CN, MY).', 'CHF ~60 million (trade estimate; private)', 70, '2024 (estimate)', 'estimate', 'INFORS HT (Bottmingen) is family-owned; a database figure of USD 17.5M looks too low for ~200 staff, so an order-of-magnitude estimate from headcount is used. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched: ''"Infors HT" Israel distributor'' and Hebrew ''Infors HT ישראל נציג'' (Hebrew hits were about the unrelated ERP vendor Infor). No Israeli distributor or office named; Israel is not among INFORS HT''s nine offices. Tooling caveat: the manufacturer''s own distributor/contact page could not be opened because the WebFetch tool returned DNS errors for every host during this run, and the shared WebSearch budget was exhausted before domain-restricted follow-up searches could run. Result reflects the English and Hebrew web searches only.', 'low', 'Headcount dated (2015); revenue only unverified estimates; Israeli channel not established.', 'company', 'partial');
