INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (97, 'Nabertherm', 'Nabertherm GmbH; Nabertherm Inc. (USA)', 'Lilienthal (near Bremen)', 'Germany', '', 'Private', 1947, 'https://nabertherm.com', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 600, 2026, '''About 600 employees worldwide'' per a 2026 Nabertherm product brochure; 2022 anniversary releases said c. 500 (English) / c. 550 in Lilienthal (German). Own subsidiaries in UK, Spain, France, Netherlands, Switzerland, Italy, China, USA.', 'EUR 65 million', 72, 'FY2021', 'company', 'Company''s 75th-anniversary press release (Sept 2022) gives c. EUR 65M revenue for 2021; Craft.co lists EUR 77.6M for FY2022 (unsourced). No 2024/2025 figure found.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched: ''"Nabertherm" Israel distributor'' and Hebrew ''Nabertherm ישראל יבואן''. The search snippet of Nabertherm''s official ''World-Wide Sales'' locator listed agents for many countries (e.g. New Zealand, Morocco, Hungary, Sweden, Türkiye, Latin America) with no Israeli entry visible, directing other countries to headquarters; the snippet was truncated so an Israeli entry cannot be ruled out. The only Israeli hit was an eBay seller in Bnei Brak offering a used Nabertherm controller (not a distributor). Nabertherm furnaces are also resold by global catalog houses (Thomas Scientific, Fisher Scientific). Tooling caveat: the manufacturer''s own distributor/contact page could not be opened because the WebFetch tool returned DNS errors for every host during this run, and the shared WebSearch budget was exhausted before domain-restricted follow-up searches could run. Result reflects the English and Hebrew web searches only.', 'low', 'Size from company releases (revenue dated 2021); official locator snippet showed no Israel entry but page could not be opened in full.', 'company', 'partial');
