INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check) VALUES (99, 'ATS Scientific Products (ex-SP Industries)', 'SP Industries; SP Scientific; ATS Life Sciences Scientific Products; SP VirTis, SP Hull, SP Genevac, SP Bel-Art, SP Wilmad-LabGlass, SP PennTech, FTS Systems, Hotpack', 'Warminster, Pennsylvania', 'USA', 'ATS Corporation', 'Subsidiary of ATS Corporation (public, TSX/NYSE: ATS)', NULL, 'https://www.scientificproducts.com', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 700, 2021, 'c. 700 employees across nine manufacturing facilities/locations in the US, UK and Spain at the time ATS agreed to acquire SP Industries (Nov 2021 ATS announcement); no newer division-level figure found.', 'USD 179 million', 179, 'TTM ending Sep-2021', 'company', 'Revenue USD 179M and adjusted EBITDA USD 29M for the twelve months ended 30 Sep 2021 per the ATS acquisition announcement (price c. USD 445M / C$550M; c. 70% North America, c. 73% biopharma & life-science equipment). Some coverage cited c. USD 223M. ATS does not report Scientific Products separately since.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). Searched: ''"ATS Scientific Products" OR "SP Scientific" Israel distributor'' and Hebrew ''VirTis Genevac SP Scientific ישראל נציג''. No Israeli distributor or representative was named (only corporate-history results and used-equipment resellers). Note the unrelated Canadian firm ATS Scientific Inc. appears in results. Tooling caveat: the manufacturer''s own distributor/contact page could not be opened because the WebFetch tool returned DNS errors for every host during this run, and the shared WebSearch budget was exhausted before domain-restricted follow-up searches could run. Result reflects the English and Hebrew web searches only.', 'low', 'Size figures official but dated to the 2021 acquisition; Israeli channel not established.', 'company', 'partial');
